insert into public.cars (id, model_id, trim_level, year, price_iqd, condition, origin, body_type, mileage_km, transmission, fuel, engine, cylinders, horsepower, drivetrain, seats, color, city, status, featured, tags, description) values
  ('car-001', 'toyota-camry', 'SE', 2024, 36000000, 'مستعملة', 'أمريكي', 'سيدان', 21000, 'أوتوماتيك', 'بنزين', '2.5L', 4, 203, 'أمامي', 5, 'أحمر', 'بغداد', 'متوفرة', true, '{}'::text[], 'تويوتا كامري SE 2024 وارد أمريكي، ممشى 21 ألف كم فقط. السيارة بدون صبغ وبدون حوادث مسجلة، فحصت بالكامل في المعرض. اقتصادية بالوقود وقطعها متوفرة بكل مكان، خيار مضمون للعائلة والاستخدام اليومي.'),
  ('car-002', 'toyota-corolla', 'SE', 2023, 25500000, 'مستعملة', 'أمريكي', 'سيدان', 34000, 'أوتوماتيك', 'بنزين', '2.0L', 4, 169, 'أمامي', 5, 'أبيض', 'البصرة', 'متوفرة', true, array['اقتصادية']::text[], 'تويوتا كورولا SE 2023 وارد أمريكي بمحرك 2.0 لتر، ممشى 34 ألف كم. من أقل السيارات استهلاكاً للوقود وتكاليف صيانتها بسيطة. حالة ممتازة ومناسبة للاستخدام اليومي.'),
  ('car-003', 'toyota-land-cruiser', 'GXR', 2026, 135000000, 'جديدة', 'خليجي', 'دفع رباعي', 0, 'أوتوماتيك', 'بنزين', '3.5L V6 توين تيربو', 6, 409, 'رباعي', 7, 'أسود', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'تويوتا لاند كروزر GXR 2026 خليجي زيرو، الدفع الرباعي الأكثر طلباً في العراق. محرك V6 سعة 3.5 لتر توين تيربو بقوة 409 حصان وناقل 10 سرعات، قوة وموثوقية للطرق الخارجية والمدينة.'),
  ('car-004', 'toyota-land-cruiser-prado', 'TXL', 2023, 76000000, 'مستعملة', 'خليجي', 'دفع رباعي', 38000, 'أوتوماتيك', 'بنزين', '4.0L V6', 6, 271, 'رباعي', 7, 'أبيض', 'أربيل', 'متوفرة', false, '{}'::text[], 'تويوتا برادو TXL 2023 خليجي بمحرك V6 سعة 4.0 لتر، آخر موديل من الجيل المعروف بالمتانة. ممشى 38 ألف كم وصيانة منتظمة، مناسبة للعوائل الكبيرة والسفر.'),
  ('car-005', 'kia-k5', 'GT-Line', 2024, 30500000, 'مستعملة', 'كوري', 'سيدان', 19000, 'أوتوماتيك', 'بنزين', '1.6L تيربو', 4, 180, 'أمامي', 5, 'أزرق', 'بغداد', 'متوفرة', true, '{}'::text[], 'كيا K5 GT-Line 2024 وارد كوري بمحرك 1.6 تيربو، تصميم رياضي وتجهيزات كاملة. ممشى 19 ألف كم وحالة شبه جديدة، فخامة بسعر مناسب.'),
  ('car-006', 'kia-sportage', 'GT-Line', 2023, 34000000, 'مستعملة', 'كوري', 'SUV', 27000, 'أوتوماتيك', 'بنزين', '1.6L تيربو', 4, 180, 'أمامي', 5, 'رمادي', 'أربيل', 'متوفرة', true, '{}'::text[], 'كيا سبورتاج GT-Line 2023 وارد كوري، الجيل الجديد بالشاشة المنحنية. SUV عملية ومريحة للعائلة، ممشى 27 ألف كم ومساحة داخلية واسعة.'),
  ('car-007', 'kia-sorento', null, 2026, 58000000, 'جديدة', 'وكالة', 'SUV', 0, 'أوتوماتيك', 'بنزين', '3.5L V6', 6, 272, 'كلي', 7, 'رمادي', 'بغداد', 'متوفرة', false, '{}'::text[], 'كيا سورينتو 2026 وكالة زيرو بمحرك V6 سعة 3.5 لتر ودفع كلي، سبعة مقاعد حقيقية للعوائل الكبيرة. ضمان الوكيل وتجهيزات أمان متقدمة.'),
  ('car-008', 'hyundai-sonata', null, 2023, 27500000, 'مستعملة', 'كوري', 'سيدان', 41000, 'أوتوماتيك', 'بنزين', '2.5L', 4, 191, 'أمامي', 5, 'أبيض', 'بغداد', 'متوفرة', false, '{}'::text[], 'هيونداي سوناتا 2023 وارد كوري، سيدان عائلية واسعة وهادئة. ممشى 41 ألف كم وسجل صيانة واضح.'),
  ('car-009', 'hyundai-tucson', null, 2024, 31000000, 'مستعملة', 'خليجي', 'SUV', 14000, 'أوتوماتيك', 'بنزين', '2.0L', 4, 156, 'أمامي', 5, 'أبيض', 'النجف', 'متوفرة', true, '{}'::text[], 'هيونداي توسان 2024 خليجي بالتصميم المحدّث، ممشى 14 ألف كم وحالة قريبة من الجديدة. تجهيزات تقنية متقدمة واستهلاك وقود معتدل.'),
  ('car-010', 'hyundai-elantra', 'SEL', 2023, 23000000, 'مستعملة', 'أمريكي', 'سيدان', 36000, 'أوتوماتيك', 'بنزين', '2.0L', 4, 147, 'أمامي', 5, 'أبيض', 'كربلاء', 'متوفرة', false, array['اقتصادية']::text[], 'هيونداي إلنترا SEL 2023 وارد أمريكي، خيار اقتصادي وعملي للاستخدام اليومي. ممشى 36 ألف كم وحالة ميكانيكية ممتازة.'),
  ('car-011', 'nissan-altima', 'SV', 2023, 26500000, 'مستعملة', 'أمريكي', 'سيدان', 31000, 'أوتوماتيك', 'بنزين', '2.5L', 4, 188, 'أمامي', 5, 'أبيض', 'بغداد', 'محجوزة', false, '{}'::text[], 'نيسان التيما SV 2023 وارد أمريكي، مريحة وهادئة القيادة مع استهلاك وقود معقول. ممشى 31 ألف كم وحالة نظيفة جداً.'),
  ('car-012', 'nissan-patrol', 'LE Platinum', 2026, 160000000, 'جديدة', 'خليجي', 'دفع رباعي', 0, 'أوتوماتيك', 'بنزين', '3.5L V6 توين تيربو', 6, 425, 'رباعي', 8, 'أسود', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'نيسان باترول LE بلاتينيوم 2026 خليجي زيرو، الجيل الجديد بمحرك V6 توين تيربو بقوة 425 حصان. فخامة كاملة ومقصورة واسعة لثمانية ركاب، رمز القوة في السوق العراقي.'),
  ('car-013', 'nissan-sunny', null, 2024, 20000000, 'مستعملة', 'وكالة', 'سيدان', 22000, 'أوتوماتيك', 'بنزين', '1.6L', 4, 118, 'أمامي', 5, 'أبيض', 'الموصل', 'متوفرة', false, array['اقتصادية']::text[], 'نيسان صني 2024 وكالة، من أكثر السيارات اقتصادية بالوقود والصيانة. ممشى 22 ألف كم، خيار موثوق لأول سيارة ولسائقي التطبيقات.'),
  ('car-014', 'chevrolet-malibu', 'LT', 2023, 22000000, 'مستعملة', 'أمريكي', 'سيدان', 44000, 'أوتوماتيك', 'بنزين', '1.5L تيربو', 4, 160, 'أمامي', 5, 'رمادي', 'بغداد', 'متوفرة', true, '{}'::text[], 'شفروليه ماليبو LT 2023 وارد أمريكي، من أكثر السيارات انتشاراً في العراق لراحتها ومساحتها الداخلية الواسعة. ممشى 44 ألف كم.'),
  ('car-015', 'chevrolet-tahoe', 'LT', 2023, 86000000, 'مستعملة', 'أمريكي', 'SUV', 33000, 'أوتوماتيك', 'بنزين', '5.3L V8', 8, 355, 'رباعي', 8, 'أسود', 'البصرة', 'متوفرة', false, array['فاخرة']::text[], 'شفروليه تاهو LT 2023 وارد أمريكي بمحرك V8 ودفع رباعي، SUV كبيرة تتسع لثمانية ركاب براحة تامة. ممشى 33 ألف كم.'),
  ('car-016', 'lexus-es-350', null, 2023, 57000000, 'مستعملة', 'أمريكي', 'سيدان', 24000, 'أوتوماتيك', 'بنزين', '3.5L V6', 6, 302, 'أمامي', 5, 'فضي', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'لكزس ES 350 2023 وارد أمريكي، فخامة يابانية هادئة مع عزل صوت ممتاز وراحة قيادة عالية. ممشى 24 ألف كم وصيانة منتظمة.'),
  ('car-017', 'lexus-rx-350', null, 2024, 76000000, 'مستعملة', 'خليجي', 'SUV', 15000, 'أوتوماتيك', 'بنزين', '2.4L تيربو', 4, 275, 'كلي', 5, 'أحمر', 'أربيل', 'متوفرة', false, array['فاخرة']::text[], 'لكزس RX 350 2024 خليجي، الجيل الجديد بمحرك 2.4 تيربو ودفع كلي. SUV فاخرة بتصميم جريء وتجهيزات أمان متقدمة، بحالة ممتازة.'),
  ('car-018', 'mercedes-c-300', 'AMG Line', 2024, 65000000, 'مستعملة', 'أمريكي', 'سيدان', 18000, 'أوتوماتيك', 'بنزين', '2.0L تيربو', 4, 255, 'خلفي', 5, 'أبيض', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'مرسيدس C 300 AMG Line موديل 2024 وارد أمريكي، أناقة ألمانية بتجهيزات تقنية حديثة. ممشى 18 ألف كم وحالة شبه جديدة.'),
  ('car-019', 'mercedes-gle-450', '4MATIC', 2026, 155000000, 'جديدة', 'خليجي', 'SUV', 0, 'أوتوماتيك', 'بنزين', '3.0L تيربو هجين خفيف', 6, 375, 'كلي', 5, 'رمادي', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'مرسيدس GLE 450 4MATIC موديل 2026 خليجي زيرو، محرك سداسي 3.0 لتر تيربو مع نظام هجين خفيف. فخامة وأداء عالي وتجهيزات كاملة.'),
  ('car-020', 'bmw-520i', 'M Sport', 2026, 91000000, 'جديدة', 'وكالة', 'سيدان', 0, 'أوتوماتيك', 'بنزين', '2.0L تيربو', 4, 208, 'خلفي', 5, 'أبيض', 'أربيل', 'متوفرة', true, array['فاخرة']::text[], 'BMW 520i M Sport موديل 2026 وكالة زيرو، الجيل الجديد من الفئة الخامسة. توازن مثالي بين الفخامة ومتعة القيادة مع ضمان الوكيل.'),
  ('car-021', 'bmw-x5', 'xDrive40i M Sport', 2026, 135000000, 'جديدة', 'خليجي', 'SUV', 0, 'أوتوماتيك', 'بنزين', '3.0L تيربو', 6, 375, 'كلي', 5, 'أسود', 'بغداد', 'متوفرة', true, array['فاخرة']::text[], 'BMW X5 xDrive40i M Sport موديل 2026 خليجي زيرو، SUV فاخرة بأداء رياضي قوي من محرك سداسي 3.0 تيربو.'),
  ('car-022', 'ford-explorer', 'XLT', 2022, 37000000, 'مستعملة', 'أمريكي', 'SUV', 58000, 'أوتوماتيك', 'بنزين', '2.3L تيربو', 4, 300, 'رباعي', 7, 'أبيض', 'بغداد', 'متوفرة', false, '{}'::text[], 'فورد إكسبلورر XLT 2022 وارد أمريكي بسبعة مقاعد ودفع رباعي، مساحة تخزين واسعة ومناسبة للرحلات العائلية. ممشى 58 ألف كم.'),
  ('car-023', 'land-rover-defender', '110 X-Dynamic SE', 2024, 118000000, 'مستعملة', 'خليجي', 'دفع رباعي', 12000, 'أوتوماتيك', 'بنزين', '3.0L تيربو هجين خفيف', 6, 395, 'كلي', 5, 'أخضر', 'أربيل', 'متوفرة', true, array['فاخرة']::text[], 'لاند روفر ديفندر 110 موديل 2024 خليجي، تصميم عصري بروح مغامرة وقدرات عبور استثنائية مع فخامة داخلية. ممشى 12 ألف كم.'),
  ('car-024', 'kia-picanto', null, 2024, 18500000, 'مستعملة', 'وكالة', 'هاتشباك', 21000, 'أوتوماتيك', 'بنزين', '1.2L', 4, 83, 'أمامي', 5, 'أبيض', 'البصرة', 'متوفرة', false, array['اقتصادية']::text[], 'كيا بيكانتو 2024 وكالة، هاتشباك صغيرة واقتصادية جداً بالوقود، مثالية للتنقل داخل المدينة وسهلة الركن. ممشى 21 ألف كم.'),
  ('car-025', 'kia-ev6', 'GT-Line AWD', 2026, 71000000, 'جديدة', 'كوري', 'SUV', 0, 'أوتوماتيك', 'كهربائي', 'كهربائي 84 kWh', null, 320, 'كلي', 5, 'رمادي', 'بغداد', 'متوفرة', true, array['كهربائية']::text[], 'كيا EV6 GT-Line موديل 2026 زيرو، كهربائية بالكامل ببطارية 84 كيلوواط ساعة ومدى قيادة يقارب 500 كم، مع شحن سريع من 10 إلى 80٪ خلال حوالي 20 دقيقة.'),
  ('car-026', 'toyota-camry', 'SE Hybrid', 2026, 49000000, 'جديدة', 'خليجي', 'سيدان', 0, 'أوتوماتيك', 'هايبرد', '2.5L هايبرد', 4, 225, 'أمامي', 5, 'أحمر', 'كربلاء', 'متوفرة', false, array['اقتصادية']::text[], 'تويوتا كامري SE هايبرد 2026 خليجي زيرو، الجيل الجديد الهجين بالكامل. توفير كبير بالوقود مع أداء سلس وهادئ وتجهيزات حديثة.'),
  ('car-027', 'honda-civic', 'Sport', 2023, 28500000, 'مستعملة', 'أمريكي', 'سيدان', 29000, 'أوتوماتيك', 'بنزين', '2.0L', 4, 158, 'أمامي', 5, 'أزرق', 'الموصل', 'متوفرة', false, '{}'::text[], 'هوندا سيفيك Sport 2023 وارد أمريكي، تصميم رياضي جذاب وقيادة ممتعة مع اقتصاد جيد بالوقود. ممشى 29 ألف كم.'),
  ('car-028', 'mitsubishi-pajero', null, 2021, 38000000, 'مستعملة', 'خليجي', 'دفع رباعي', 72000, 'أوتوماتيك', 'بنزين', '3.8L V6', 6, 247, 'رباعي', 7, 'أبيض', 'السليمانية', 'متوفرة', false, '{}'::text[], 'ميتسوبيشي باجيرو 2021 خليجي بمحرك V6 سعة 3.8 لتر، آخر سنة إنتاج للموديل. دفع رباعي قوي وموثوق للطرق الوعرة والاستخدام العائلي.'),
  ('car-029', 'toyota-hilux', 'دبل قمارة', 2024, 49000000, 'مستعملة', 'خليجي', 'شاحنة', 26000, 'أوتوماتيك', 'بنزين', '2.7L', 4, 164, 'رباعي', 5, 'أبيض', 'الموصل', 'متوفرة', false, '{}'::text[], 'تويوتا هايلكس 2024 دبل قمارة خليجي بمحرك 2.7 لتر ودفع رباعي، بيكب قوي وموثوق للعمل والطرق الخارجية. ممشى 26 ألف كم.'),
  ('car-030', 'changan-cs75-plus', null, 2026, 46000000, 'جديدة', 'وكالة', 'SUV', 0, 'أوتوماتيك', 'بنزين', '2.0L تيربو', 4, 233, 'أمامي', 5, 'رمادي', 'بغداد', 'متوفرة', true, '{}'::text[], 'شانجان CS75 بلس 2026 وكالة زيرو بمحرك 2.0 تيربو، من أكثر SUV الصينية طلباً في العراق. تجهيزات كاملة بسعر منافس مع ضمان الوكيل.'),
  ('car-031', 'geely-coolray', null, 2026, 34000000, 'جديدة', 'وكالة', 'SUV', 0, 'أوتوماتيك', 'بنزين', '1.5L تيربو', 4, 177, 'أمامي', 5, 'أبيض', 'البصرة', 'متوفرة', false, array['اقتصادية']::text[], 'جيلي كولراي 2026 وكالة زيرو، SUV مدمجة رياضية بمحرك 1.5 تيربو وناقل DCT بسبع سرعات. اقتصادية ومناسبة للشباب والمدينة.'),
  ('car-032', 'haval-h6', null, 2026, 44000000, 'جديدة', 'وكالة', 'SUV', 0, 'أوتوماتيك', 'بنزين', '2.0L تيربو', 4, 234, 'أمامي', 5, 'بيج', 'أربيل', 'متوفرة', false, '{}'::text[], 'هافال H6 2026 وكالة زيرو، SUV عائلية واسعة بمحرك 2.0 تيربو وتجهيزات تقنية متقدمة، مع ضمان الوكيل.'),
  ('car-033', 'hyundai-santa-fe', null, 2026, 71000000, 'جديدة', 'خليجي', 'SUV', 0, 'أوتوماتيك', 'بنزين', '2.5L تيربو', 4, 277, 'كلي', 7, 'أخضر', 'بغداد', 'متوفرة', true, '{}'::text[], 'هيونداي سنتافي 2026 خليجي زيرو، الجيل الجديد بالتصميم المربع الواسع وسبعة مقاعد. محرك 2.5 تيربو ودفع كلي، خيار مثالي للعائلة الكبيرة.'),
  ('car-034', 'chery-tiggo-8-pro-max', null, 2026, 48000000, 'جديدة', 'وكالة', 'SUV', 0, 'أوتوماتيك', 'بنزين', '2.0L تيربو', 4, 254, 'كلي', 7, 'أبيض', 'بغداد', 'متوفرة', false, '{}'::text[], 'شيري تيغو 8 برو ماكس 2026 وكالة زيرو، SUV بسبعة مقاعد ودفع كلي ومحرك 2.0 تيربو، تجهيزات فخمة بسعر منافس وضمان الوكيل.')
